INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000005b',1,'APPROVED','PUBLISHED',
'{"objectives":["Report what someone else said in Kannada","Use avaru heLidaare ki for reported speech","Convert direct speech to indirect speech"],"explanation":{"intro":"Reported speech covers how to tell someone else what another person said — one of the most common patterns in everyday conversation in Kannada.","culturalNote":"Reported speech in Karnataka culture: sharing what others said is extremely common — in family conversations (amma heLidaLe ki = mother said that), in news discussions (TV alli heLidaare ki = they said on TV that), in gossip, in relaying messages. The ''anta'' vs ''ki'' pattern: both are used — anta is more Kannada, ki is borrowed from Urdu/Hindi and very common in Bengaluru colloquial speech. Rumor vs fact: Kannadigas distinguish between ''keLidini'' (I heard — may not be true) and ''nodide'' (I saw — firsthand). Common reported speech topics: cricket score, current events, family news, work gossip, neighbor''s activities. Formal reported speech: in formal writing, indirect speech uses -endra form (heLidaare endra = they said thus). Colloquial shortcut: ''avanu X anta heLda'' (he said X — very casual — heLda = said, colloquial past)."},"examples":[{"sentence":"Nanna mitranu heLidaane ki naale shuTTi ide — office bandilla anta.","english":"My friend said that tomorrow there is a holiday — (they said) they won''t come to the office."},{"sentence":"News alli heLidaare ki Bengaluru ge naale maLe barutte.","english":"They said on the news that it will rain in Bengaluru tomorrow."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can report what others said using reported speech in Kannada."}}',
'{"items":[{"word":"heLidaare ki","translation":"said that (they said that — formal reported speech)","transliteration":"heLidaare ki","pronunciation":"he-LI-daa-re ki","example":"heLidaare ki naale..."},{"word":"anta","translation":"(that) — indirect speech marker (Kannada version)","transliteration":"anta","pronunciation":"AN-ta","example":"baruttini anta heLida"},{"word":"ki","translation":"that (conjunction — Urdu/Hindi borrowed — very common)","transliteration":"ki","pronunciation":"ki","example":"heLidaare ki..."},{"word":"keLidini","translation":"I heard (hearsay — may not be confirmed)","transliteration":"keLidini","pronunciation":"ke-Li-DI-ni","example":"keLidini ki..."},{"word":"shuTTi","translation":"holiday/day off (from office)","transliteration":"shuTTi","pronunciation":"SHUT-Ti","example":"naale shuTTi ide"},{"word":"anta heLda","translation":"said (that) — casual past reported speech","transliteration":"anta heLda","pronunciation":"AN-ta HEL-da","example":"baruttini anta heLda"}]}',
'{"title":"Avaru heLidaare ki X — reported speech in Kannada (they said that X)","pattern":"Avaru heLidaare ki X = They said that X (ki = that connector). Avanu X anta heLida = He said X (anta = that, informal). Kari: keLidini ki X = I heard that X. Past: avaru X anta heLidaare (they said X — anta = that). Question: avaru enu heLidaare? = what did they say? Reply with ki: avaru ki... heLidaare (they said that...).","explanation":"Reported speech in Kannada: direct: avanu ''baruttini'' anta heLida (he said ''I will come''). Indirect: avanu baruttaane anta heLida (he said that he will come — note pronoun change). The ''anta'' marker: X anta heLida = said that X (anta links the reported speech). The ''ki'' marker: heLidaare ki X = said that X (ki from Hindi/Urdu, very common in urban Kannada). Questions reported: avaru elli hoguttira anta keeLidaare (they asked where you are going). Commands reported: avaru banni anta heLidaare (they said please come). Tense: in Kannada, the tense in reported speech often stays the same (backshifting is not obligatory unlike English).","examples":[{"sentence":"Avaru heLidaare ki next month namma company alli navin project shuru aagutte.","english":"They said that next month a new project will start in our company."},{"sentence":"Nanna amma heLidaLe ki raatri bega mane baa anta.","english":"My mother said (that) come home early tonight."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"anta means?","options":["(that) — indirect speech marker","and","but","then"],"correctAnswer":"(that) — indirect speech marker"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My friend said that tomorrow there is a holiday — (they said) they won''t come to the office.","options":["Nanna mitranu heLidaane ki naale shuTTi ide — office bandilla anta.","Nanna mitranu heLidaane ki inja shuTTi ide — office bandilla anta.","Nanna mitranu heLidaane ki naale shuTTi ide — office hoguttini anta.","Nanna geleti heLidaaLe ki naale shuTTi ide — office bandilla anta."],"correctAnswer":"Nanna mitranu heLidaane ki naale shuTTi ide — office bandilla anta."},{"id":"ex3","type":"FILL_IN_BLANK","question":"News alli heLidaare ki Bengaluru ge naale maLe ___ .","options":["barutte","bande","baruttide","bardarbeekaagi"],"correctAnswer":"barutte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: They said that next month a new project will start in our company.","wordBankItems":["Avaru","heLidaare","ki","next","month","namma","company","alli","navin","project","shuru","aagutte","."],"correctAnswer":"Avaru heLidaare ki next month namma company alli navin project shuru aagutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"keLidini means?","options":["I heard (hearsay — may not be confirmed)","I saw","I know","I believe"],"correctAnswer":"I heard (hearsay — may not be confirmed)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000005c',1,'APPROVED','PUBLISHED',
'{"objectives":["Form conditional sentences in Kannada","Use aadare X maaduttini / -odadare Y for if-then","Express hypothetical and real conditions"],"explanation":{"intro":"Conditional sentences in Kannada cover both real conditions (if it rains, I will bring an umbrella) and hypothetical conditions (if I had money, I would travel).","culturalNote":"Conditional thinking in Karnataka: Kannadigas use conditionals very naturally in daily conversation — especially in negotiating, planning, and expressing caution. Weather conditions: common topic — maLe bandare (if rain comes), beshige aadare (if it''s hot). Work conditions: boss mundeyalli (if the boss is in front — meaning: if the boss is present/watching, behavior changes!). Traffic conditions: traffic kammi aadare bega baruttini (if traffic is less, I''ll come quickly). Food conditions: neenu baruttiya aadare oota maaduttini (if you come, I''ll cook food). Negotiation: X kammagi koDuttiri aadare koDuttini (if you give X at a cheaper price, I''ll take it — classic market negotiation). Superstition/folk wisdom: conditional proverbs: maLe bittare (after rain stops), beLigge ezhuttiduva aadare (if you wake up in the morning — implying good things follow)."},"examples":[{"sentence":"Naale maLe bandare naanu meeting ge hoguttilla.","english":"If rain comes tomorrow I will not go to the meeting."},{"sentence":"Naakke hana aadare naanu hosa car koDuttidde.","english":"If I had money I would have bought a new car."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can form real and hypothetical conditional sentences in Kannada."}}',
'{"items":[{"word":"bandare","translation":"if (it) comes — conditional suffix -are/dare","transliteration":"bandare","pronunciation":"BAN-da-re","example":"maLe bandare"},{"word":"aadare","translation":"if/but — dual use word (aadare alone = ''but'', X aadare = if X)","transliteration":"aadare","pronunciation":"AA-da-re","example":"maLe aadare"},{"word":"hoguttilla","translation":"I will not go (negative future)","transliteration":"hoguttilla","pronunciation":"ho-GUT-til-la","example":"meeting ge hoguttilla"},{"word":"koDuttidde","translation":"I would have given/bought (hypothetical past)","transliteration":"koDuttidde","pronunciation":"ko-DUT-tid-de","example":"koDuttidde aadare"},{"word":"bahudu","translation":"might/may/could (possibility marker)","transliteration":"bahudu","pronunciation":"BA-hu-du","example":"baruvabahudu"},{"word":"illadidare","translation":"if not/if there isn''t — negative conditional","transliteration":"illadidare","pronunciation":"il-la-di-DA-re","example":"neeru illadidare"}]}',
'{"title":"Maale bandare X maaduttini — conditional sentences in Kannada","pattern":"X bandare Y maaduttini = if X comes I will do Y. Verb + -are/-dare = if/when (conditional suffix). Real condition: maLe bandare chatri tooguttini (if it rains, I''ll take an umbrella). Hypothetical: hana aadare hoguttidde (if there was money, I would have gone). Negative: X illadidare Y (if there is no X, then Y). Unless: X maadadidare Y agutte (if you don''t do X, Y will happen).","explanation":"Conditional in Kannada: (1) Real conditional (something likely): verb + -are suffix. Baa + -are = baadare (if it comes). HoG + -odadare = hogodadare (if you go). More common: maLe bandare (if rain comes — baa + -ndare). (2) Hypothetical (unlikely/impossible): verb + -uttidde (1st person: what I would do). Naakke hana aadare X koDuttidde (if I had money, I would have given X). (3) Negative conditional: X illadidare (if X is not there). (4) Unless: X maadadidare Y agutte (if X is not done, Y will happen). Common conditional sentence topics: weather (maLe), traffic (traffic), money (hana), health (channaagi iddare).","examples":[{"sentence":"Neevu beLigge bega ezhuttidare traffic kammi ide, office ge bega siguttade.","english":"If you get up early in the morning, there is less traffic, and the office will be reached quickly."},{"sentence":"Naakke swalpa time aadare naanu nimage sahaaya maaduttini.","english":"If I have a little time, I will help you."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"bandare means?","options":["if (it) comes — conditional","when it came","after coming","it came"],"correctAnswer":"if (it) comes — conditional"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"If rain comes tomorrow I will not go to the meeting.","options":["Naale maLe bandare naanu meeting ge hoguttilla.","Inja maLe bandare naanu meeting ge hoguttilla.","Naale beshige bandare naanu meeting ge hoguttilla.","Naale maLe bandare avanu meeting ge hoguttaane."],"correctAnswer":"Naale maLe bandare naanu meeting ge hoguttilla."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naakke swalpa time ___ naanu nimage sahaaya maaduttini.","options":["aadare","bandare","illadidare","aaddarinda"],"correctAnswer":"aadare"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: If you get up early in the morning, there is less traffic, and the office will be reached quickly.","wordBankItems":["Neevu","beLigge","bega","ezhuttidare","traffic","kammi","ide",",","office","ge","bega","siguttade","."],"correctAnswer":"Neevu beLigge bega ezhuttidare traffic kammi ide , office ge bega siguttade ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"bahudu means?","options":["might/may/could (possibility)","must/should","will","can"],"correctAnswer":"might/may/could (possibility)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000005d',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe how things have changed over time in Kannada","Use hinde vs abhi contrast for change","Talk about Bengaluru''s growth and development"],"explanation":{"intro":"Changes over time vocabulary covers how to describe how things were before and how they are now — a common pattern for discussing development, personal growth, and social change in Kannada.","culturalNote":"Change in Karnataka: Karnataka and especially Bengaluru has undergone dramatic transformation. Bengaluru: from a ''pensioners'' paradise'' (retired people''s quiet city) in the 1980s to Asia''s Silicon Valley. Population: grew from 1 million in 1960 to 12+ million today. Traffic: major issue — once famous for gardens and parks, now famous for traffic. Green cover: Bengaluru had over 280 lakes in the 1960s — many have been encroached upon, but efforts to restore (Jakkur Lake, Ulsoor Lake restoration). Language: Kannada has absorbed many English and Hindi words — linguistic change over decades. Agriculture: Karnataka''s shift from primarily agricultural to service-based economy over 50 years. Village to city: mass migration from districts to Bengaluru for IT jobs — many first-generation city dwellers. Nostalgia: the ''hinde Bengaluru'' (old Bengaluru) narrative is very common — Kannadigas fondly remember the old, quieter city."},"examples":[{"sentence":"Hinde Bengaluru thumba shanta aagiutte — abhi thumba traffic haagu noise ide.","english":"Earlier Bengaluru used to be very quiet — now there is a lot of traffic and noise."},{"sentence":"Naanu hinde bhaara taruva aagiutte, abhi thumba channa baaLuttiddeeni.","english":"Earlier I used to be very shy, now I am living much more confidently."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe how things have changed over time in Kannada."}}',
'{"items":[{"word":"hinde","translation":"before/earlier/in the past","transliteration":"hinde","pronunciation":"HIN-de","example":"hinde aagiutte itu"},{"word":"abhi","translation":"now/at present","transliteration":"abhi","pronunciation":"AB-hi","example":"abhi hege ide?"},{"word":"badalaavaNi","translation":"change/transformation","transliteration":"badalaavaNi","pronunciation":"ba-da-laa-VA-Ni","example":"thumba badalaavaNi"},{"word":"beLadu","translation":"growth/development (beLuvudu = growing)","transliteration":"beLadu","pronunciation":"BE-la-du","example":"Bengaluru beLadu"},{"word":"hinna paristithi","translation":"old situation/former condition","transliteration":"hinna paristithi","pronunciation":"HIN-na pa-ris-TI-thi","example":"hinna paristithi"},{"word":"abhi paristithi","translation":"current situation/present condition","transliteration":"abhi paristithi","pronunciation":"AB-hi pa-ris-TI-thi","example":"abhi paristithi"}]}',
'{"title":"Hinde X aagiutte, abhi Y aagutte — describing change over time in Kannada","pattern":"Hinde X aagiutte (itu) = earlier it used to be X. Abhi Y aagutte = now it is Y. Contrast: hinde X, abhi Y — placing before vs now. Cause of change: yaakenendare Z = because Z (giving the reason for change). Personal change: naanu hinde X maaduttidde, abhi Y maaduttini (earlier I used to do X, now I do Y).","explanation":"Change vocabulary in Kannada: hinde (before/earlier), abhi (now/currently). Describing past state: X aagiutte itu (it used to be X — aagiutte itu = it used to happen/be). Current state: abhi X aagutte (now it is X). Evolution: X inda Y aayitu (X became Y). Improvement: thumba oLLeyaagi badelaavaNe aagide (much good change has happened). Deterioration: sthiti keDide (the situation has worsened — sthiti = situation, keDide = spoiled/worsened). Personal growth: naanu badelaagide (I have changed). City change: hinde X jitagaLu itu, abhi X yokshyaagi badelaagide (earlier there were X trees, now they have reduced significantly).","examples":[{"sentence":"Ee ooru hinde baaLeyo aagiutte itu, abhi thumba aabhivruddhi aagide.","english":"This town used to be a developing place, now it has developed a lot."},{"sentence":"Naanu hinde Kannada maatnaaDuttiddilla, abhi channaagi maatnaaDuttiddeeni.","english":"Earlier I did not speak Kannada, now I speak it well."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"badalaavaNi means?","options":["change/transformation","development","improvement","growth"],"correctAnswer":"change/transformation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Earlier Bengaluru used to be very quiet — now there is a lot of traffic and noise.","options":["Hinde Bengaluru thumba shanta aagiutte — abhi thumba traffic haagu noise ide.","Abhi Bengaluru thumba shanta aagutte — hinde thumba traffic haagu noise itu.","Hinde Bengaluru thumba shanta aagiutte — hinde thumba traffic haagu noise itu.","Hinde Mysuru thumba shanta aagiutte — abhi thumba traffic haagu noise ide."],"correctAnswer":"Hinde Bengaluru thumba shanta aagiutte — abhi thumba traffic haagu noise ide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu hinde Kannada maatnaaDuttiddilla, ___ channaagi maatnaaDuttiddeeni.","options":["abhi","hinde","munde","naale"],"correctAnswer":"abhi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Earlier I used to be very shy, now I am living much more confidently.","wordBankItems":["Naanu","hinde","bhaara","taruva","aagiutte",",","abhi","thumba","channa","baaLuttiddeeni","."],"correctAnswer":"Naanu hinde bhaara taruva aagiutte , abhi thumba channa baaLuttiddeeni ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"abhi means?","options":["now/at present","before","then","earlier"],"correctAnswer":"now/at present"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000005e',1,'APPROVED','PUBLISHED',
'{"objectives":["Express wishes and hopes in Kannada","Use naakke X aagabeku anta ishtavagutte for wishing","Talk about life dreams and aspirations"],"explanation":{"intro":"Wishes and hopes vocabulary covers how to express what you wish for, what you hope will happen, and your dreams for the future in Kannada.","culturalNote":"Wishing culture in Karnataka: expressing wishes is common in festivals, ceremonies, and everyday life. New Year wish: Ugaadi habba shubhashayagalu (Happy Ugaadi)! Kannada Rajyotsava: November 1 — Kannada Rajyotsava shubhashayagalu (Happy Karnataka Formation Day)! Wedding: Shubha Mangala Savadhan (auspicious wedding chant). Birthday: Huttida habba habbada shubhashayagalu (Happy Birthday wishes)! Aspirational culture: education and career aspirations are strong in Karnataka. IIT dream (IIT ge select aagabeku anta wish) is a cultural trope. South Indian mother''s famous aspiration: ''nanna maga doctor/engineer aagabeku'' (my son should become a doctor/engineer). Karnataka-specific aspiration: working in Infosys/Wipro/TCS or starting a startup — very aspirational. Rural aspiration: own land, cow, prosperous harvest. Urban aspiration: own apartment, car, secure job."},"examples":[{"sentence":"Naakke ondu sala Europe ge hogabeku anta thumba ishtavagutte.","english":"I really wish I could go to Europe once."},{"sentence":"Nanna maga doctor aagabeku anta naanna amma wish iti.","english":"My mother''s wish was that my son should become a doctor."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express wishes, hopes, and aspirations in Kannada."}}',
'{"items":[{"word":"wish","translation":"wish (English word used directly)","transliteration":"wish","pronunciation":"wish","example":"nanna wish"},{"word":"aagabeku anta","translation":"wish that X should happen","transliteration":"aagabeku anta","pronunciation":"aa-ga-BE-ku AN-ta","example":"X aagabeku anta ishtavagutte"},{"word":"kaanike","translation":"gift/boon/blessing wished for","transliteration":"kaanike","pronunciation":"KAA-ni-ke","example":"devara kaanike"},{"word":"svapna","translation":"dream (ambition/hope)","transliteration":"svapna","pronunciation":"SVAP-na","example":"nanna svapna"},{"word":"aakaanksha","translation":"aspiration/strong desire","transliteration":"aakaanksha","pronunciation":"aa-KAAN-ksha","example":"nanna aakaanksha"},{"word":"samruddha","translation":"prosperous/well-off","transliteration":"samruddha","pronunciation":"sam-RUD-dha","example":"samruddha jiivana"}]}',
'{"title":"Naakke X aagabeku anta ishtavagutte — wishes and aspirations in Kannada","pattern":"Naakke X aagabeku anta ishtavagutte = I wish X would happen. X aagabeku = X should happen (wish). Svapna: nanna svapna X maaduvudu (my dream is to do X). Aakaanksha: nanna aakaanksha X (my aspiration is X). Wish for others: nimage X aagali anta ashiisisuttini (I bless you/hope X happens for you — ashiisisuttini = I bless). Unlikely wish: kaash X aadidare (if only X had happened — kaash = if only, a wish marker borrowed from Urdu).","explanation":"Wish vocabulary in Kannada: wish (wish — English), svapna (dream/aspiration — from Sanskrit), aakaanksha (strong desire/aspiration), kaanike (divine gift/boon — used in religious context: devara kaanike sigali = may I get God''s blessing). Expressing wishes: X aagabeku anta ishtavagutte (I want X to happen), X aagabeku anta aashisuttini (I hope X happens). For others: nimage oLLeyaagali (may good happen to you — oLLeyaagali = may it be good, optative mood). Optative (blessing) mood: -ali ending expresses a wish: barali (may it come), aagali (may it happen), sigali (may it be received). Kaash + hypothetical: kaash naanu bega hode idhre (if only I had gone earlier — expressing regret as wish).","examples":[{"sentence":"Namma deshakke samruddha bhavishya aagali anta naanu wish maaduttini.","english":"I wish that a prosperous future comes to our country."},{"sentence":"Kaash naanu cricket alli try maadidre, nanna svapna itu aadare aagalilla.","english":"If only I had tried in cricket, it was my dream but it didn''t happen."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"svapna means?","options":["dream (ambition/hope)","wish","hope","desire"],"correctAnswer":"dream (ambition/hope)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I really wish I could go to Europe once.","options":["Naakke ondu sala Europe ge hogabeku anta thumba ishtavagutte.","Naakke ondu sala America ge hogabeku anta thumba ishtavagutte.","Naakke eradu sala Europe ge hogabeku anta thumba ishtavagutte.","Naakke ondu sala Europe ge hogabeku anta thakku ishtavagutte."],"correctAnswer":"Naakke ondu sala Europe ge hogabeku anta thumba ishtavagutte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Namma deshakke samruddha bhavishya ___ anta naanu wish maaduttini.","options":["aagali","aagutte","aayitu","bandare"],"correctAnswer":"aagali"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My mother''s wish was that my son should become a doctor.","wordBankItems":["Nanna","maga","doctor","aagabeku","anta","naanna","amma","wish","itu","."],"correctAnswer":"Nanna maga doctor aagabeku anta naanna amma wish itu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aakaanksha means?","options":["aspiration/strong desire","wish","dream","hope"],"correctAnswer":"aspiration/strong desire"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000005f',1,'APPROVED','PUBLISHED',
'{"objectives":["Give complex descriptions of people and places in Kannada","Combine multiple adjectives in descriptions","Use relative clauses for more detailed descriptions"],"explanation":{"intro":"Complex descriptions covers how to provide detailed, multi-element descriptions of people and places using compound adjectives, relative clauses, and linked descriptive phrases.","culturalNote":"Descriptive language in Karnataka: Kannada literature is famous for its rich descriptive language — from classical poetry (vachana literature by Basavanna and other Sharanas) to modern novels. Descriptive language in Kannada tends toward lyricism. Landscape description: Western Ghats descriptions in Kannada literature use layered natural imagery. City descriptions: Bengaluru is often described in paradoxical terms — modern and traditional, crowded and beautiful, stressful and exciting. People descriptions: in Kannada films, the hero''s entry scene (entry scene) always includes elaborate descriptions. Descriptive tradition: Janapada (folk) songs use very vivid descriptive language for nature and people. Real estate: apartment brochures use highly descriptive Kannada text combining English technical terms and Kannada poetry to sell properties."},"examples":[{"sentence":"Avarige nodi — avaru thumba ucchai, hasi bana shirt haakkonDu, notebook hattikkonDu baruttaare, nanna new manager.","english":"Look at them — they are very tall, wearing a green shirt, carrying a notebook, my new manager."},{"sentence":"Namma ooru ondu channa betta mele iru — alli inda Bengaluru nadiige nodabahud, kaaveri naadi thumba channa kaanabahudu.","english":"Our village is on a beautiful hill — from there you can see Bengaluru at night, the Kaveri river can be seen beautifully."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can give complex, multi-element descriptions of people and places in Kannada."}}',
'{"items":[{"word":"haakkonDu","translation":"wearing/having put on (continuous wearing)","transliteration":"haakkonDu","pronunciation":"haak-KON-Du","example":"shirt haakkonDu"},{"word":"hattikkonDu","translation":"holding/carrying (continuously)","transliteration":"hattikkonDu","pronunciation":"hat-tik-KON-Du","example":"notebook hattikkonDu"},{"word":"nadiige","translation":"at night (time expression)","transliteration":"nadiige","pronunciation":"na-DII-ge","example":"nadiige nodabahud"},{"word":"kaanabahudu","translation":"can be seen (possibility of seeing)","transliteration":"kaanabahudu","pronunciation":"kaa-na-BA-hu-du","example":"channa kaanabahudu"},{"word":"layered","translation":"layered/complex (English word used for complex descriptions)","transliteration":"layered","pronunciation":"LAY-erd","example":"layered description"},{"word":"vivara","translation":"detail/description (giving details)","transliteration":"vivara","pronunciation":"VI-va-ra","example":"vivara kodi"}]}',
'{"title":"Complex descriptions — combining adjectives and relative clauses in Kannada","pattern":"Complex person description: [height] + [wearing X] + [carrying Y] + [at location Z] + [who is my A]. Combining adjectives: thumba ucchai, hasi bana shirt haakkonDu, notebook hattikkonDu baruttaare (very tall, wearing green shirt, carrying notebook, coming). Place description: [location] + [what you can see from there] + [what is special] + [who lives there]. Participial phrases: -konDu suffix = while doing/having done (haakkonDu = wearing, hattikkonDu = carrying).","explanation":"Complex descriptions in Kannada: chain adjectives before noun: thumba ucchai, kaaLu kaLLa (very tall, black-haired — before noun). Participial phrases (-konDu = while doing): haakkonDu (while wearing), hattikkonDu (while carrying), naaduttaakkonDu (while walking). These can be chained: shirt haakkonDu, hattu hattikkonDu, naaduttaakkonDu baruttaare (coming while wearing a shirt, carrying a bag, and walking). Subordinate description: X ondu Y — using ondu as article before description. Relative clause: X maaduvavaru (those who do X — -vavaru = the ones who), X naadida manushya (the person who walked X — past participle + manushya). High descriptive quality: combine setting + character + action + mood.","examples":[{"sentence":"Avaru ondu shanta manushya — hinde ooru inda bandavaru, abhi Bengaluru alli IT industry alli channa kaela maaduttaare.","english":"They are a quiet person — having come from a village, now working well in Bengaluru''s IT industry."},{"sentence":"Ee jagada baaninalli ondu dodda mara ide, avara neDalu beLigge soorya beLake thiLiyo maadiguttade.","english":"In this place''s colour there is a big tree, under it in the morning, sunlight filters through beautifully."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"haakkonDu means?","options":["wearing/having put on (continuous)","taking off","putting on now","wearing (past)"],"correctAnswer":"wearing/having put on (continuous)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Look at them — they are very tall, wearing a green shirt, carrying a notebook, my new manager.","options":["Avarige nodi — avaru thumba ucchai, hasi bana shirt haakkonDu, notebook hattikkonDu baruttaare, nanna new manager.","Avanige nodi — avanu thumba ucchai, hasi bana shirt haakkonDu, notebook hattikkonDu baruttaane, nanna new manager.","Avarige nodi — avaru thakku ucchai, hasi bana shirt haakkonDu, notebook hattikkonDu baruttaare, nanna new manager.","Avarige nodi — avaru thumba ucchai, kempu bana shirt haakkonDu, notebook hattikkonDu baruttaare, nanna new manager."],"correctAnswer":"Avarige nodi — avaru thumba ucchai, hasi bana shirt haakkonDu, notebook hattikkonDu baruttaare, nanna new manager."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Namma ooru ondu channa betta mele iru — alli inda Bengaluru nadiige ___ .","options":["nodabahud","noduttini","nodide","nodabeku"],"correctAnswer":"nodabahud"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: They are a quiet person — having come from a village, now working well in Bengaluru''s IT industry.","wordBankItems":["Avaru","ondu","shanta","manushya","—","hinde","ooru","inda","bandavaru",",","abhi","Bengaluru","alli","IT","industry","alli","channa","kaela","maaduttaare","."],"correctAnswer":"Avaru ondu shanta manushya — hinde ooru inda bandavaru , abhi Bengaluru alli IT industry alli channa kaela maaduttaare ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kaanabahudu means?","options":["can be seen (possibility)","must be seen","was seen","is seen"],"correctAnswer":"can be seen (possibility)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000060',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss plans and possibilities in Kannada","Use -bahudu for possibility and maadabeku for intention","Express certainty, probability, and possibility"],"explanation":{"intro":"Plans and possibilities vocabulary covers a range of certainty levels — from definite plans to remote possibilities — in Kannada.","culturalNote":"Planning culture in Karnataka: Kannadigas value careful planning but also embrace uncertainty — the phrase ''aaguttade'' (it will happen/work out) reflects an optimistic fatalism. ''Devara dayaadi'' (by God''s grace) — used when planning for something hopeful but uncertain. Major planning events: career path planning (common in late teens/early 20s — college choices, entrance exams), marriage planning (families plan for months/years), pilgrimage planning (booking temple darshana slots months in advance — especially Tirupati, Dharmasthala). Business planning: startups — Bengaluru''s startup culture values MVP (minimum viable product) and lean planning. Monsoon planning: farmers plan crop cycles around monsoon. Infrastructure planning: Bengaluru Metro expansion — planned for decades, executing in phases. ''Naale aagutte'' (tomorrow it will happen) — a gentle Karnataka optimism about bureaucratic delays!"},"examples":[{"sentence":"Naanu next month Europe trip maadabahudu anta yochane iddini aadare nishchaya aagilla.","english":"I am thinking I might take a Europe trip next month but it is not certain."},{"sentence":"Ee project next quarter poorthi aagutte anta nambuttiddeeni — bahudu aagutte.","english":"I believe this project will be completed next quarter — it might happen."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express plans with different levels of certainty and possibility in Kannada."}}',
'{"items":[{"word":"bahudu","translation":"might/may/could (possibility — used with verb)","transliteration":"bahudu","pronunciation":"BA-hu-du","example":"aagutte bahudu"},{"word":"nishchaya","translation":"certainty/definite decision","transliteration":"nishchaya","pronunciation":"NISH-cha-ya","example":"nishchaya aagilla"},{"word":"shaayada","translation":"maybe/perhaps (Urdu borrowed — very common)","transliteration":"shaayada","pronunciation":"SHAA-ya-da","example":"shaayada baruttini"},{"word":"definitely","translation":"definitely (English word used directly)","transliteration":"definitely","pronunciation":"DEF-ni-tlee","example":"definitely hoguttini"},{"word":"cancel","translation":"cancel/call off","transliteration":"cancel","pronunciation":"KAN-sel","example":"plan cancel aayitu"},{"word":"postpone","translation":"postpone/delay","transliteration":"postpone","pronunciation":"post-PON","example":"meeting postpone aayitu"}]}',
'{"title":"Bahudu, shaayada, nishchayavaagi — expressing possibility and certainty in Kannada","pattern":"X bahudu = X might happen (possibility). X definitely aagutte = X will definitely happen. Shaayada X = maybe X. Nishchayavaagi = certainly/definitely. Plan with uncertainty: X maadabeku anta yochane ide aadare nishchaya aagilla (I plan to do X but it is not certain). Confirmed plan: naanu definitely X maaduttini (I will definitely do X).","explanation":"Possibility markers in Kannada: high certainty: nishchayavaagi / definitely hoguttini (I will definitely go). Medium certainty: X maaduttini anta plan ide (I have a plan to do X). Low certainty: X maadabahudu (I might do X). Uncertain: shaayada X (maybe X — Urdu/Hindi borrowed). Remote: X maadabahudu anta tharkavaagithe (considering whether might do X). Asking: neevu definitely baruttiri aa? (are you definitely coming?). Response options: howdu, definitely baruttini (yes, definitely coming), shaayada baruttini (maybe coming), nishchaya aagilla (it''s not certain), hogalaarenu (can''t come). Contingent plan: X aadare Y maaduttini (if X happens, I will do Y).","examples":[{"sentence":"Naane shaayada naale baruttini — aadare nishchaya aagilla, confirm maaduttini.","english":"Maybe I will come tomorrow — but it is not certain, I will confirm."},{"sentence":"Trip definitely aagutte, tickets book maadiddivi — bahudu next week leave siguttade.","english":"The trip will definitely happen, we have booked tickets — we might get leave next week."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"bahudu means?","options":["might/may/could (possibility)","must","will","should"],"correctAnswer":"might/may/could (possibility)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am thinking I might take a Europe trip next month but it is not certain.","options":["Naanu next month Europe trip maadabahudu anta yochane iddini aadare nishchaya aagilla.","Naanu next month Europe trip maadabahudu anta yochane iddini aadare nishchaya aayitu.","Naanu next year Europe trip maadabahudu anta yochane iddini aadare nishchaya aagilla.","Avanu next month Europe trip maadabahudu anta yochane iddaane aadare nishchaya aagilla."],"correctAnswer":"Naanu next month Europe trip maadabahudu anta yochane iddini aadare nishchaya aagilla."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naane ___ naale baruttini — aadare nishchaya aagilla, confirm maaduttini.","options":["shaayada","nishchayavaagi","definitely","bayakaagi"],"correctAnswer":"shaayada"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Maybe I will come tomorrow — but it is not certain, I will confirm.","wordBankItems":["Naane","shaayada","naale","baruttini","—","aadare","nishchaya","aagilla",",","confirm","maaduttini","."],"correctAnswer":"Naane shaayada naale baruttini — aadare nishchaya aagilla , confirm maaduttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"shaayada means?","options":["maybe/perhaps","definitely","certainly","probably"],"correctAnswer":"maybe/perhaps"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000061',1,'APPROVED','PUBLISHED',
'{"objectives":["Give detailed step-by-step instructions in Kannada","Use prathama, nantara, kaDeyalli for instruction sequencing","Describe a recipe or process step by step"],"explanation":{"intro":"Giving detailed instructions covers how to explain a multi-step process — like a recipe, a how-to, or directions — with clarity and sequencing in Kannada.","culturalNote":"Instruction-giving culture in Karnataka: recipe sharing is very important in Karnataka culture. Mothers pass recipes to daughters (and increasingly sons!). Recipe books (pachaka vidhi pustaka) are common gifts at weddings. YouTube cooking channels: Kannada cooking channels like Bengaluru Foodies, Vanitha TV cooking shows are very popular. Karnataka recipes are elaborate — bisi bele bath has 30+ ingredients! BBMP instructions (civic notices) are in Kannada. Government scheme instructions: many Karnataka government schemes publish instructions in Kannada for rural beneficiaries. Recipe precision: Karnataka cooking tends to use precise measurements — one of the reasons Udupi cuisine (Udupi brahmin cooking style) is considered one of the most precise in India. Troubleshooting: in IT, giving instructions (steps) is a daily activity — ''first do this, then do that'' is very familiar language."},"examples":[{"sentence":"Filter kaapi maaduva vidhi: prathama coffee powder filter alli haaku, nantara boiling neeru suri, kaDeyalli haalu haagu sakkare kali.","english":"Method to make filter coffee: first put coffee powder in the filter, then pour boiling water, finally add milk and sugar."},{"sentence":"Ee app install maaduva steps: prathama Play Store ge hogi, nantara app search maadu, kaDeyalli install click maadu.","english":"Steps to install this app: first go to Play Store, then search for the app, finally click install."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can give clear, detailed step-by-step instructions in Kannada."}}',
'{"items":[{"word":"vidhi","translation":"method/recipe/procedure","transliteration":"vidhi","pronunciation":"VI-dhi","example":"maaduva vidhi"},{"word":"steps","translation":"steps (English word used)","transliteration":"steps","pronunciation":"steps","example":"ee steps nodiri"},{"word":"suri","translation":"pour (imperative — pour liquid)","transliteration":"suri","pronunciation":"SU-ri","example":"neeru suri"},{"word":"kali","translation":"mix/stir (imperative — combine ingredients)","transliteration":"kali","pronunciation":"KA-li","example":"sakkare kali"},{"word":"bisi maadu","translation":"heat up/make hot","transliteration":"bisi maadu","pronunciation":"BI-si MAA-du","example":"bisi maadi"},{"word":"kaluhi","translation":"boil (imperative — for water/liquids)","transliteration":"kaluhi","pronunciation":"ka-LU-hi","example":"neeru kaluhi"}]}',
'{"title":"Vidhi — step-by-step instructions in Kannada","pattern":"Prathama X maadu, nantara Y kali, kaDeyalli Z suri = First do X, then mix Y, finally pour Z. Imperative forms: haaku (put), kali (mix), suri (pour), kaDi (cut), bisi maadu (heat), kaluhi (boil). For instructions to others: neevu X maadiri (you do X — polite). Step numbers: ondu (1st step), eraDu (2nd step), mooru (3rd step). Total: eshtu steps? (how many steps?).","explanation":"Instruction vocabulary in Kannada: imperatives for instructions: haaku (put — haaKiri = formal), kali (mix/stir — kaLiri = formal), suri (pour — suriri = formal), kaDi (cut — kaDiri = formal), bisi maadu (heat up), kaluhi (boil — kaluhiri = formal), tadisi (stir-fry — tadisiri = formal). Time markers: X nimisha (X minutes), X gante (X hours), bega (quickly), meLLege (slowly). Temperature: jaasthi bisinappe (high heat), kammi bisinappe (low heat). Texture: thakkagannide (enough thick), thakkaagi beLeyitu (cooked enough). Checking: taste nodiri (taste-check please — nodiri = please see). Recipe format: ingredients (ingredients) first, then steps (steps / vidhi). Kannada recipe suffix: -iri (for formal instructions), -u (for informal).","examples":[{"sentence":"Saaru maaduvudu: prathama tomato, eeruLLi, hasi menasu kaluhi, nantara tamarind neeru kali, kaDeyalli saaru podi haagu uppinakaayi haaku.","english":"To make saaru: first boil tomato, onion, green chilli, then mix tamarind water, finally add saaru powder and pickle."},{"sentence":"Ee form fill maaduva vidhi: prathama name haaku, nantara date haaku, kaDeyalli sign maadiri.","english":"Method to fill this form: first put name, then put date, finally please sign."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"vidhi means?","options":["method/recipe/procedure","recipe ingredients","cooking","style"],"correctAnswer":"method/recipe/procedure"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Method to make filter coffee: first put coffee powder in the filter, then pour boiling water, finally add milk and sugar.","options":["Filter kaapi maaduva vidhi: prathama coffee powder filter alli haaku, nantara boiling neeru suri, kaDeyalli haalu haagu sakkare kali.","Filter kaapi maaduva vidhi: nantara coffee powder filter alli haaku, prathama boiling neeru suri, kaDeyalli haalu haagu sakkare kali.","Filter kaapi maaduva vidhi: prathama coffee powder filter alli haaku, nantara boiling neeru kali, kaDeyalli haalu haagu sakkare suri.","Filter kaapi maaduva vidhi: prathama tea powder filter alli haaku, nantara boiling neeru suri, kaDeyalli haalu haagu sakkare kali."],"correctAnswer":"Filter kaapi maaduva vidhi: prathama coffee powder filter alli haaku, nantara boiling neeru suri, kaDeyalli haalu haagu sakkare kali."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ee form fill maaduva vidhi: prathama name haaku, nantara date haaku, kaDeyalli ___ maadiri.","options":["sign","suri","kali","kaluhi"],"correctAnswer":"sign"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Steps to install this app: first go to Play Store, then search the app, finally click install.","wordBankItems":["Ee","app","install","maaduva","steps",":","|","prathama","Play","Store","ge","hogi",",","nantara","app","search","maadu",",","kaDeyalli","install","click","maadu","."],"correctAnswer":"Ee app install maaduva steps : | prathama Play Store ge hogi , nantara app search maadu , kaDeyalli install click maadu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kaluhi means?","options":["boil (imperative)","heat up","fry","mix"],"correctAnswer":"boil (imperative)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000062',1,'APPROVED','PUBLISHED',
'{"objectives":["Express regret and apology in Kannada","Use naakke sorry aagutte and kshamisi for apologies","Acknowledge mistakes and express remorse"],"explanation":{"intro":"Regret and apology vocabulary covers how to say sorry, acknowledge a mistake, and express genuine remorse in Kannada.","culturalNote":"Apology culture in Karnataka: apologizing directly is sometimes considered a social vulnerability in traditional Kannada culture — especially among elders and men. However, among younger generations and in professional settings, direct apology is more common. ''Sorry'' (English word) is universally used and understood. Formal Kannada apology: kshamisi (please forgive — formal), kshamaapaNe kori (I ask for forgiveness — very formal). Religious context: confession and forgiveness in temples — Devaru kshamisi (God forgive me — common prayer phrase). Indirect apology: ''naakke gottilla'' (I didn''t know — indirect admission of error), ''naadu tappu aaythu'' (my mistake happened — acknowledging error without explicit sorry). Professional: email/message apologies use ''sorry for the inconvenience'' directly in English. Overusing sorry: in urban Bengaluru, ''sorry'' is used very freely — ''sorry ma, phone busy aagiutte itu'' (sorry the phone was busy)."},"examples":[{"sentence":"Naakke thumba sorry, naanu tappu maadide — nimage hurt maadabeku aagirlilla.","english":"I am very sorry, I made a mistake — I shouldn''t have hurt you."},{"sentence":"Dayavittu kshamisi, naakke gottillaa — bega helpless aagiutte.","english":"Please forgive me, I didn''t know — I felt very helpless quickly."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express regret, apologize, and acknowledge mistakes in Kannada."}}',
'{"items":[{"word":"kshamisi","translation":"please forgive (formal apology)","transliteration":"kshamisi","pronunciation":"KSHA-mi-si","example":"dayavittu kshamisi"},{"word":"tappu","translation":"mistake/error","transliteration":"tappu","pronunciation":"TAP-pu","example":"nanna tappu"},{"word":"hurt maadabeku aagirlilla","translation":"shouldn''t have hurt (expressing regret)","transliteration":"hurt maadabeku aagirlilla","pronunciation":"hurt MAA-da-be-ku aa-GIR-lil-la","example":"hurt maadabeku aagirlilla"},{"word":"helpless","translation":"helpless (English word used)","transliteration":"helpless","pronunciation":"HELP-les","example":"naakke helpless aagutte"},{"word":"pashchaattaapa","translation":"regret/remorse","transliteration":"pashchaattaapa","pronunciation":"pash-chaat-TAA-pa","example":"thumba pashchaattaapa ide"},{"word":"sorry aagutte","translation":"I feel sorry/apologetic (naakke sorry aagutte)","transliteration":"sorry aagutte","pronunciation":"SOR-ri aa-GUT-te","example":"naakke sorry aagutte"}]}',
'{"title":"Kshamisi, naakke sorry aagutte — expressing regret and apology in Kannada","pattern":"Naakke sorry aagutte = I feel sorry / I am sorry. Kshamisi = please forgive (formal). Nanna tappu = my mistake. X maadabeku aagirlilla = shouldn''t have done X (regret). Pashchaattaapa: naakke thumba pashchaattaapa ide (I have a lot of regret). Acknowledging error: nanna tappu aaythu, dayavittu kshamisi (it was my mistake, please forgive me).","explanation":"Apology vocabulary in Kannada: sorry (universally used — English), kshamisi (forgive — kshamaapaNe = forgiveness), tappu (mistake — nanna tappu = my mistake, avana tappu = his mistake). Expressing regret: X maadabeku aagirlilla (shouldn''t have done X — aagirlilla = it shouldn''t have been). Strong regret: naakke pashchaattaapa aagutte (I feel regret). Accepting apology: parenthetical: aagutte, problem illa (it''s okay, no problem), kshamisideevi (we have forgiven — kshamisi + deevi = we-did). Not forgiving (serious): naakke kshamisi maaduva aagutte aguttilla (I can''t forgive). Indirect apology: naakke gottalla itu (I didn''t know — implies the mistake was unintentional). Making amends: naanu X maaduttini anta nambuttini — saridu maaduttini (I will fix it — saridu = fix/correct).","examples":[{"sentence":"Meeting ge late aadane — naakke sorry, traffic thumba heavy itu.","english":"I was late to the meeting — I''m sorry, the traffic was very heavy."},{"sentence":"Nanna naaDadalli nimage novu koTTe anta nambuttini — dayavittu kshamisi.","english":"I believe my behavior caused you pain — please forgive me."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"tappu means?","options":["mistake/error","regret","apology","mistake"],"correctAnswer":"mistake/error"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am very sorry, I made a mistake — I shouldn''t have hurt you.","options":["Naakke thumba sorry, naanu tappu maadide — nimage hurt maadabeku aagirlilla.","Nimage thumba sorry, naanu tappu maadide — nimage hurt maadabeku aagirlilla.","Naakke thakku sorry, naanu tappu maadide — nimage hurt maadabeku aagirlilla.","Naakke thumba sorry, naanu tappu maadide — nimage hurt maadabeku aagutte."],"correctAnswer":"Naakke thumba sorry, naanu tappu maadide — nimage hurt maadabeku aagirlilla."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Meeting ge late aadane — naakke sorry, traffic thumba ___ itu.","options":["heavy","challu","channa","bisinappe"],"correctAnswer":"heavy"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I believe my behavior caused you pain — please forgive me.","wordBankItems":["Nanna","naaDadalli","nimage","novu","koTTe","anta","nambuttini","—","dayavittu","kshamisi","."],"correctAnswer":"Nanna naaDadalli nimage novu koTTe anta nambuttini — dayavittu kshamisi ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kshamisi means?","options":["please forgive (formal apology)","please understand","please help","please come"],"correctAnswer":"please forgive (formal apology)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000063',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Karnataka''s music and literature in Kannada","Name major Kannada authors and musicians","Express appreciation for cultural works"],"explanation":{"intro":"Karnataka''s music and literature covers the major cultural figures, literary movements, and musical traditions of the state with vocabulary to discuss them in Kannada.","culturalNote":"Karnataka''s literary heritage: (1) Ancient Kannada literature (Hale Kannada): Pampa (Adi Kavi Pampa — 10th century — the first great Kannada poet — Vikramarjuna Vijaya), Ponna, Ranna — the Three Gems of early Kannada. (2) Vachana movement (12th century): Basavanna (founder of Lingayat reform movement — vachanas = short spiritual prose poems), Akkamahadevi (woman saint-poet), Allama Prabhu. The vachanas are famous for their direct, simple spiritual language. (3) Modern Kannada: Kuvempu (K.V. Puttappa — Jnanpith award — national poet — ''Kuvempu'' pen name — ''Ramayana Darshanam'' his magnum opus). D.R. Bendre (Jnanpith award — Kannada lyric poetry). Masti Venkatesha Iyengar (short story master). U.R. Ananthamurthy (Jnanpith award — ''Samskara'' novel). Poornachandra Tejaswi (P. Lankesh''s son — nature writing, science writing). (4) Carnatic music: M.S. Subbalakshmi was Tamil but loved in Karnataka; Karnataka has many great Carnatic musicians. (5) Film music: Raju Ananthaswamy, C. Ashwath — famous Kannada bhavageethe (devotional-romantic songs) composers."},"examples":[{"sentence":"Basavannana vachana Kannada saahityada thumba muhtvada bhaaga — avara vachana saadha bhaasheyalli thumba gaaLha artha ide.","english":"Basavanna''s vachanas are a very important part of Kannada literature — their vachanas have very deep meaning in simple language."},{"sentence":"Kuvempu Karnataka''s national poet — avara ''Ramayana Darshanam'' ondu adbhuta mahakaavya.","english":"Kuvempu is Karnataka''s national poet — their ''Ramayana Darshanam'' is an amazing epic poem."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss Karnataka''s literature and music in Kannada."}}',
'{"items":[{"word":"saahitya","translation":"literature","transliteration":"saahitya","pronunciation":"SAA-hi-tya","example":"Kannada saahitya"},{"word":"kavana","translation":"poem/poetry","transliteration":"kavana","pronunciation":"ka-VA-na","example":"channa kavana"},{"word":"kavi","translation":"poet","transliteration":"kavi","pronunciation":"KA-vi","example":"mahaan kavi"},{"word":"vachana","translation":"vachana (short prose poem — Basavanna''s literary form)","transliteration":"vachana","pronunciation":"VA-cha-na","example":"Basavanna vachana"},{"word":"bhavageethe","translation":"lyric devotional song (Kannada musical genre)","transliteration":"bhavageethe","pronunciation":"bha-va-GEE-the","example":"channa bhavageethe"},{"word":"Jnanpith","translation":"Jnanpith Award (India''s highest literary award)","transliteration":"Jnanpith","pronunciation":"GYAN-pith","example":"Jnanpith award"}]}',
'{"title":"Kannada saahitya — literature and music vocabulary","pattern":"X Kannada saahityada muhtvada lekhaka = X is an important author of Kannada literature. X Jnanpith award sigitaare = X received the Jnanpith award. Kavana: X kavana thumba gaaLha artha ide (X''s poem has very deep meaning). Bhavageethe: Kannada bhavageethe noduvudu naakke ishtavagutte (I like listening to Kannada bhavageethe). Appreciating: ee kavana nambella mana muttuttade (this poem touches everyone''s hearts).","explanation":"Karnataka literature vocabulary: saahitya (literature), kavana/kaavya (poem/poetry), naaTaka (drama/play), kathe (story), kadambari (novel), vachana (Basavanna''s prose poems). Authors: lekhaka (author — m), lekhaki (author — f), kavi (poet). Literary terms: gaaLha (deep/profound), saaLa (straightforward/simple), artha (meaning). Awards: Jnanpith Award (highest Indian literary award — Karnataka has 8 awardees). Music terms: bhavageethe (lyric devotional song — Karnataka specific — not classical, not film — emotional). Carnatic music: raaga (raaga/melody), taaLa (rhythm). Film songs: cine haaDu. Devotional: keertane/haaDu. Listening: haaDu keLuttini (I am listening to a song). Cultural experience: saahitya sammelana (literary conference — held annually in Karnataka — very popular).","examples":[{"sentence":"Naanu Kuvempu avara Ramayana Darshanam odikonDiddeeni — adbhuta saahitya aduude.","english":"I have been reading Kuvempu''s Ramayana Darshanam — it is truly amazing literature."},{"sentence":"Basavannana vachana nagara tanadinalli thumba prasiddha — naakke idara artha nambabeku anta ishtavagutte.","english":"Basavanna''s vachanas are very popular even in today''s times — I want to understand their meaning."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"vachana means?","options":["vachana (Basavanna''s short prose poem)","verse","story","poem"],"correctAnswer":"vachana (Basavanna''s short prose poem)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Basavanna''s vachanas are a very important part of Kannada literature — their vachanas have very deep meaning in simple language.","options":["Basavannana vachana Kannada saahityada thumba muhtvada bhaaga — avara vachana saadha bhaasheyalli thumba gaaLha artha ide.","Kuvempuva vachana Kannada saahityada thumba muhtvada bhaaga — avara vachana saadha bhaasheyalli thumba gaaLha artha ide.","Basavannana kavana Kannada saahityada thumba muhtvada bhaaga — avara vachana saadha bhaasheyalli thumba gaaLha artha ide.","Basavannana vachana Kannada saahityada thakku muhtvada bhaaga — avara vachana saadha bhaasheyalli thumba gaaLha artha ide."],"correctAnswer":"Basavannana vachana Kannada saahityada thumba muhtvada bhaaga — avara vachana saadha bhaasheyalli thumba gaaLha artha ide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu Kuvempu avara Ramayana Darshanam odikonDiddeeni — adbhuta ___ aduude.","options":["saahitya","kavana","vachana","bhavageethe"],"correctAnswer":"saahitya"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Kuvempu is Karnataka''s national poet — their ''Ramayana Darshanam'' is an amazing epic poem.","wordBankItems":["Kuvempu","Karnataka''s","national","poet","—","avara","Ramayana","Darshanam","ondu","adbhuta","mahakaavya","."],"correctAnswer":"Kuvempu Karnataka''s national poet — avara Ramayana Darshanam ondu adbhuta mahakaavya ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"bhavageethe means?","options":["lyric devotional song (Karnataka genre)","classical music","film song","devotional hymn"],"correctAnswer":"lyric devotional song (Karnataka genre)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000064',1,'APPROVED','PUBLISHED',
'{"objectives":["Review all A2 grammar patterns introduced in lessons 91-99","Demonstrate A2 conversation skills","Prepare for further Kannada learning beyond A2"],"explanation":{"intro":"A2 Milestone review consolidates reported speech, conditionals, change over time, wishes, complex descriptions, possibilities, instructions, regret, and cultural vocabulary from Karnataka.","culturalNote":"Completing Kannada through lesson 100: you have now completed the first 100 lessons of Kannada! You have covered A1 (lessons 1-90) and started A2 (lessons 91-100). Your skills now include: A1 skills: all basic vocabulary, three tenses, family, shopping, transport, health, food, culture. New A2 skills: reported speech (anta heLida/ki), conditionals (-are/-dare), changes over time (hinde vs abhi), wishes (aagabeku anta), complex descriptions (haakkonDu, -konDu phrases), possibility (bahudu), instructions (vidhi — step-by-step), regret and apology (kshamisi, tappu), cultural depth (literature, music). Karnataka cultural knowledge: Basavanna, Kuvempu, Yakshagana, Hampi, Dasara, filter kaapi, bisi bele bath, Western Ghats, RCB, Bengaluru IT culture. You are ready to continue Kannada learning at A2 level with more complex themes!"},"examples":[{"sentence":"Avaru heLidaare ki naale maLe bandare pariksha postpone aagutte — naakke santosha aayitu!","english":"They said that if rain comes tomorrow the exam will be postponed — I was happy about that!"},{"sentence":"Hinde Kannada kalivudu kashtavaagutte itu, abhi thumba easy aagutte — practice inda badalaavaNe aagutte!","english":"Earlier learning Kannada used to be difficult, now it is much easier — change comes through practice!"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I have completed 100 Kannada lessons and mastered A1 + early A2 skills!"}}',
'{"items":[{"word":"avara heLide","translation":"what they said (their statement)","transliteration":"avara heLide","pronunciation":"a-VA-ra he-LI-de","example":"avara heLide keLide"},{"word":"practice","translation":"practice","transliteration":"practice","pronunciation":"PRAK-tis","example":"practice maadabeku"},{"word":"nooRu","translation":"one hundred (100)","transliteration":"nooRu","pronunciation":"NOO-Ru","example":"nooRu lessons"},{"word":"kali mukki","translation":"learning completed / lesson done","transliteration":"kali mukki","pronunciation":"KA-li MUK-ki","example":"kali mukki aayitu"},{"word":"munde saagona","translation":"let''s continue/proceed further","transliteration":"munde saagona","pronunciation":"MUN-de SAA-go-na","example":"munde saagona"},{"word":"milestones","translation":"milestones (English term used)","transliteration":"milestones","pronunciation":"MAIL-stonz","example":"milestones achieve maadide"}]}',
'{"title":"A2 milestone review — 100 lessons completed!","pattern":"A2 skills summary: reported speech = X anta heLida/heLidaare ki. Conditional = X bandare/-are Y aagutte. Change = hinde X aagiutte, abhi Y aagutte. Wish = X aagabeku anta ishtavagutte. Possibility = X bahudu. Instructions = prathama X, nantara Y, kaDeyalli Z. Apology = kshamisi, tappu, pashchaattaapa. Literature = Basavanna, Kuvempu, vachana.","explanation":"A2 grammar mastered: (1) Reported speech: X anta heLida (said X) / heLidaare ki X (said that X). (2) Conditional: verb+-are/-dare (if), verb+-uttidde (would have). (3) Change: hinde X aagiutte (used to be), abhi Y aagutte (now is). (4) Wishes: X aagabeku anta ishtavagutte (wish X would happen), aagali optative. (5) Complex description: haakkonDu / hattikkonDu participials. (6) Possibility: bahudu (might), shaayada (maybe), nishchayavaagi (definitely). (7) Instructions: prathama/nantara/kaDeyalli sequence. (8) Apology: kshamisi, nanna tappu aaythu. (9) Literature/culture depth. Next steps: A2 continues with more complex reading, writing, and conversational patterns in formal and informal registers. Shubhashayagalu! Munde saagona!","examples":[{"sentence":"Naanu 100 Kannada lessons poorthi maadide — practice inda hecchaagi kalivona!","english":"I have completed 100 Kannada lessons — let''s learn more through practice!"},{"sentence":"Shubhashayagalu! Neevu Kannada kali mukki maaduttiddiri — munde A2, A3, B1 saaguvudu!","english":"Congratulations! You are completing Kannada learning — the path ahead to A2, A3, B1 awaits!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"munde saagona means?","options":["let''s continue/proceed further","let''s go back","let''s start over","let''s finish"],"correctAnswer":"let''s continue/proceed further"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"They said that if rain comes tomorrow the exam will be postponed — I was happy about that!","options":["Avaru heLidaare ki naale maLe bandare pariksha postpone aagutte — naakke santosha aayitu!","Avaru heLidaare ki inja maLe bandare pariksha postpone aagutte — naakke santosha aayitu!","Avaru heLidaare ki naale challu bandare pariksha postpone aagutte — naakke santosha aayitu!","Naanu heLide ki naale maLe bandare pariksha postpone aagutte — naakke santosha aayitu!"],"correctAnswer":"Avaru heLidaare ki naale maLe bandare pariksha postpone aagutte — naakke santosha aayitu!"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu 100 Kannada lessons poorthi maadide — ___ inda hecchaagi kalivona!","options":["practice","vidhi","saahitya","lesson"],"correctAnswer":"practice"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I have completed 100 Kannada lessons — let''s learn more through practice!","wordBankItems":["Naanu","100","Kannada","lessons","poorthi","maadide","—","practice","inda","hecchaagi","kalivona","!"],"correctAnswer":"Naanu 100 Kannada lessons poorthi maadide — practice inda hecchaagi kalivona !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"kali mukki means?","options":["learning completed / lesson done","start learning","continue learning","study more"],"correctAnswer":"learning completed / lesson done"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

